 const pages=[
  'To whoever finds this city after us,\n\n'+(finds[0]?'It has had more than one name. Listen for the people inside each of them.':'There is a line here for a name I have not learned to hear yet.')+'\n\n'+(finds[1]?'I found a little key and imagined a warm room. A city’s history has an inside.':'I have left room for the story behind a closed window.')+'\n\n'+(finds[2]?'The postcard is mended. Its view is still only the beginning of what I want to tell you.':'The edges of this picture are still waiting to be joined.'),
  (finds[3]?'I kept a fallen leaf, and left the living branch alone. Some gifts become useful long after the giver has gone.':'There is room on this page for the shade of a tree.')+'\n\n'+(story.done[1]?story.garden===0?'We planted shade beside a bench, for a tired person we may never meet.':'We planted a flowering bed, for someone who needs a reason to look up.':'A small public garden is still waiting for a decision.')+(town.margin>=0?'\n\n'+['The reading circle kept the original page carefully, so another reader could hear its first voice.','The reading circle left room in the margin for another person’s handwriting.','The reading circle left a question open, for the next reader to answer.'][town.margin]:'')+'\n\n'+(finds[4]?'Music fills the old synagogue. I want to listen without forgetting the Jewish lives behind its walls.':'A programme is waiting somewhere along the river. I have not heard that page yet.'),
  (finds[5]?'The thread led me to a crossing. The route survived a bridge that could not survive its century.':'The crossing has another story I have not gathered yet.')+'\n\n'+(story.done[2]?'We lit three lamps. Now a string of little fires makes the next few steps easier to see.':'Some lamps still need a patient hand.')+'\n\n'+'I leave this letter '+['for those who came before us.','for those sharing the city with us.','for those who have yet to arrive.'][verse]+'\n\n'+(smallCount()===6?'All six small stories are here. The city is still larger than the letter.'+(field.gathered?' Tonight its people gathered by the river, and the lights found a way to share the dark.':''):'There are still blank lines. I will keep walking.')
 ];
 wrap(letterPage===2&&archiveState.account>=0?pages[2].split('\n\n').slice(0,2).join('\n\n')+'\n\n'+accountLines[archiveState.account]+'\n\n'+['For those before us.','For those beside us.','For those after us.'][verse]+(field.gathered?' The city gathered beside the river.':''):pages[letterPage],x,b.y+155,tw,w<600?16:18,C.white);button('‹',x,b.y+b.hh-66,44,42,()=>letterPage=(letterPage+2)%3);text(`${letterPage+1} / 3`,x+72,b.y+b.hh-52,14,C.gold);button('›',x+122,b.y+b.hh-66,44,42,()=>letterPage=(letterPage+1)%3);button('Map',x+tw-95,b.y+b.hh-66,95,42,()=>change('map'));dismissButton(b.x+b.ww-pad-96,b.y+22);
